try (PreparedStatement ps = con.prepareStatement("SELECT id, email FROM customer")) {
    ResultSet rs = ps.executeQuery();
    ResultSetMetaData md = rs.getMetaData();          // column header
    CachedRowSet set = RowSetProvider.newFactory().createCachedRowSet();
    set.populate(rs);                                 // now detached from the connection
    while (set.next()) {
        String email = set.getString("email");        // name access via the row set
        System.out.println(email);
    }
}
